"use client";

import React, { useState, useRef } from "react";
import { cn } from "@/lib/utils";

export interface HoldConfirmButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  label?: string;
  onConfirmed?: () => void;
}

export function HoldConfirmButton({
  label = "Hold to Confirm",
  onConfirmed,
  className,
  ...props
}: HoldConfirmButtonProps) {
  const [holdTime, setHoldTime] = useState(0);
  const [confirmed, setConfirmed] = useState(false);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  const handleStart = () => {
    if (confirmed) return;
    timerRef.current = setInterval(() => {
      setHoldTime((prev) => {
        if (prev >= 100) {
          clearInterval(timerRef.current!);
          setConfirmed(true);
          onConfirmed?.();
          return 100;
        }
        return prev + 5;
      });
    }, 40);
  };

  const handleEnd = () => {
    if (confirmed) return;
    if (timerRef.current) clearInterval(timerRef.current);
    setHoldTime(0);
  };

  return (
    <button
      type="button"
      onMouseDown={handleStart}
      onMouseUp={handleEnd}
      onMouseLeave={handleEnd}
      onTouchStart={handleStart}
      onTouchEnd={handleEnd}
      onClick={confirmed ? () => { setConfirmed(false); setHoldTime(0); } : undefined}
      className={cn(
        "relative flex items-center justify-center gap-2 rounded-2xl px-6 py-3 text-sm font-semibold transition-all select-none cursor-pointer border shadow-md",
        confirmed
          ? "bg-emerald-600 text-white border-emerald-500"
          : "bg-rose-950 text-rose-200 border-rose-800 hover:bg-rose-900",
        className
      )}
      {...props}
    >
      <svg className="h-5 w-5 -rotate-90">
        <circle
          cx="10"
          cy="10"
          r="8"
          stroke="currentColor"
          strokeWidth="2"
          className="opacity-20"
          fill="none"
        />
        <circle
          cx="10"
          cy="10"
          r="8"
          stroke="currentColor"
          strokeWidth="2"
          fill="none"
          strokeDasharray="50"
          strokeDashoffset={50 - (50 * holdTime) / 100}
          className="text-white transition-all duration-75"
        />
      </svg>
      <span>{confirmed ? "Confirmed!" : label}</span>
    </button>
  );
}

export default HoldConfirmButton;
